internal static class CafeteriaAcceptancePage
{
    internal const string Body = """
<section class="panel"><h2>Diagnostics Level 1 · Acceptance Tests</h2><label for="acceptanceApplication">Application</label> <select id="acceptanceApplication"><option value="">Select an application</option><option value="Aegis.Cafeteria.Services">Aegis.Cafeteria.Services</option></select><p class="muted">Only applications with an implemented acceptance suite are listed. Acceptance runs require explicit authorization and isolated test databases; routine Level 5 checks do not launch them.</p></section>
<section id="acceptanceDetails" hidden><section class="metrics"><div class="metric"><b id="cafDevelopment">Unproven</b><small>Development Complete</small></div><div class="metric"><b id="cafIntegration">Unproven</b><small>Integration Proven</small></div><div class="metric"><b id="cafUat">Unproven</b><small>Ready for User Acceptance</small></div></section>
<section class="panel"><h2>Available suite: Cafeteria end-to-end acceptance</h2><p class="muted">Financial proofs execute in the isolated FFP and SQLite acceptance environment. Passing evidence does not disable legacy FFP Manager actions.</p><label>Engineering reason <input id="cafReason" maxlength="500" placeholder="Deployment or release being qualified"></label> <button id="cafRun" disabled>Run complete acceptance suite</button> <span id="cafExecution" role="status"></span></section>
<section class="panel"><h2>Execution history</h2><select id="cafHistory" aria-label="Select acceptance execution"></select><p id="cafVersion" class="muted"></p><div class="table-scroll"><table><thead><tr><th>Proof</th><th>Status</th><th>Expected</th><th>Actual</th><th>Timestamp</th></tr></thead><tbody id="cafProofs"></tbody></table></div></section>
<section class="panel"><h2>Diagnostic details</h2><pre id="cafLogs" style="white-space:pre-wrap"></pre></section></section>
""";
    internal const string Script = """
const cafSelect=document.getElementById('cafHistory'), cafButton=document.getElementById('cafRun');let cafRuns=[];
const acceptanceApplication=document.getElementById('acceptanceApplication');
function acceptanceApi(){return '/api/operations/acceptance/'+encodeURIComponent(acceptanceApplication.value);}
function cafShow(){const run=cafRuns.find(x=>x.diagnostic.runId===cafSelect.value);const rows=document.getElementById('cafProofs');rows.replaceChildren();if(!run){document.getElementById('cafLogs').textContent='';document.getElementById('cafVersion').textContent='No acceptance executions. Integration remains unproven.';return;}
document.getElementById('cafVersion').textContent=`Application ${run.applicationVersion} · Schema ${run.schemaVersion} · Suite ${run.suiteVersion} · Isolation ${run.isolationVerified?'verified':'unverified'} · ${run.diagnostic.runState} · ${run.diagnostic.completedAt}`;
for(const proof of run.proofs){const tr=document.createElement('tr');for(const value of [proof.id+' '+proof.name,proof.state,proof.expected,proof.actual,proof.atUtc]){const td=document.createElement('td');td.textContent=value;tr.append(td);}rows.append(tr);}
document.getElementById('cafLogs').textContent=run.proofs.map(p=>`${p.id} [${p.state}] ${p.detail}`).join('\n');}
async function cafLoad(){const application=acceptanceApplication.value;if(!application)return;try{const response=await fetch(acceptanceApi(),{cache:'no-store'});if(!response.ok)throw Error('Acceptance status HTTP '+response.status);const data=await response.json();if(acceptanceApplication.value!==application)return;const selected=cafSelect.value;cafRuns=data.history||[];cafSelect.replaceChildren();for(const run of cafRuns){const option=document.createElement('option');option.value=run.diagnostic.runId;option.textContent=`${run.diagnostic.startedAt} · ${run.proofs.filter(p=>p.state==='Passed').length}/${run.proofs.length} passed`;cafSelect.append(option);}if(cafRuns.some(r=>r.diagnostic.runId===selected))cafSelect.value=selected;
document.getElementById('cafDevelopment').textContent=data.release.developmentComplete?'Proven':'Unproven';document.getElementById('cafIntegration').textContent=data.release.integrationProven?'Proven':'Unproven';document.getElementById('cafUat').textContent=data.release.readyForUserAcceptance?'Ready':'Unproven';cafButton.disabled=!data.canRun||(data.execution&&!data.execution.completedAt);document.getElementById('cafExecution').textContent=data.execution?(data.execution.completedAt?'Last execution exit code '+data.execution.exitCode:'Acceptance running…'):'';cafShow();}catch(error){document.getElementById('cafExecution').textContent=error.message;cafButton.disabled=true;}}
cafSelect.addEventListener('change',cafShow);cafButton.addEventListener('click',async()=>{const reason=document.getElementById('cafReason').value.trim();if(!reason){document.getElementById('cafExecution').textContent='Enter an engineering reason.';return;}cafButton.disabled=true;try{const response=await fetch(acceptanceApi()+'/run',{method:'POST',headers:{'Content-Type':'application/json','X-Aegis-Action':'cafeteria-acceptance'},body:JSON.stringify({reason})});if(!response.ok)throw Error(await response.text());await cafLoad();}catch(error){document.getElementById('cafExecution').textContent=error.message;}});acceptanceApplication.addEventListener('change',()=>{document.getElementById('acceptanceDetails').hidden=!acceptanceApplication.value;cafButton.disabled=true;cafLoad();});setInterval(cafLoad,5000);
""";
}
